-- ============================================================
--  Seed leaderboard awal (data ASLI dari game, pakai user_id Roblox).
--
--  - Statement 1: rekor SPEEDRUN (best_time_ms), summit = 0
--  - Statement 2: total SUMMIT, best_time_ms = null
--  - Pemain yang ada di dua-duanya akan DIGABUNG oleh ON CONFLICT:
--      summit       = nilai tertinggi
--      best_time_ms = waktu tercepat (null aman)
--  - Karena memakai user_id asli, saat pemain main di game datanya
--    akan ter-update otomatis ke baris yang sama (tidak dobel).
--
--  Jalankan di Supabase: SQL Editor -> New query -> paste -> Run.
-- ============================================================

on conflict (user_id) do update set
  username = excluded.username,
  display_name = excluded.display_name,
  summit = greatest(public.players.summit, excluded.summit),
  best_time_ms = case
    when public.players.best_time_ms is null then excluded.best_time_ms
    when excluded.best_time_ms is null then public.players.best_time_ms
    else least(public.players.best_time_ms, excluded.best_time_ms)
  end;

on conflict (user_id) do update set
  username = excluded.username,
  display_name = excluded.display_name,
  summit = greatest(public.players.summit, excluded.summit),
  best_time_ms = case
    when public.players.best_time_ms is null then excluded.best_time_ms
    when excluded.best_time_ms is null then public.players.best_time_ms
    else least(public.players.best_time_ms, excluded.best_time_ms)
  end;
